import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(s.longestValidParentheses("(()")!=2||s.longestValidParentheses(")()())")!=4||s.longestValidParentheses("")!=0)throw new AssertionError();for(int n=0;n<=12;n++)for(int mask=0;mask<(1<<n);mask++){StringBuilder b=new StringBuilder();for(int i=0;i<n;i++)b.append((mask&(1<<i))==0?'(':')');String a=b.toString();int w=0;for(int l=0;l<n;l++){int balance=0;for(int j=l;j<n;j++){balance+=a.charAt(j)=='('?1:-1;if(balance<0)break;if(balance==0)w=Math.max(w,j-l+1);}}if(s.longestValidParentheses(a)!=w)throw new AssertionError(a);}if(s.longestValidParentheses("(".repeat(15000)+")".repeat(15000))!=30000)throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}}